def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = []
    op = []
    for i in range(n):
        me.append(history[i][0])
        op.append(history[i][1])

    if n == 1:
        if op[0] == 'C':
            return 'C'
        return 'D'

    last_opp = op[-1]
    last_me = me[-1]

    total_c = 0
    my_c = 0
    for i in range(n):
        if op[i] == 'C':
            total_c += 1
        if me[i] == 'C':
            my_c += 1
    total_d = n - total_c
    total_ratio = total_c / n

    recent_len = 12
    if n < recent_len:
        recent_len = n
    recent_c = 0
    start_recent = n - recent_len
    for i in range(start_recent, n):
        if op[i] == 'C':
            recent_c += 1
    recent_ratio = recent_c / recent_len

    run_opp_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            run_opp_d += 1
        else:
            break

    run_dd = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and op[i] == 'D':
            run_dd += 1
        else:
            break

    mirror = 0
    tot = 0
    for i in range(1, n):
        tot += 1
        if me[i - 1] == op[i]:
            mirror += 1
    mirror_ratio = mirror / tot if tot > 0 else 0.0

    periodic = False
    if n >= 18 and mirror_ratio < 0.55 and total_c > 0 and total_d > 0:
        best_match = 0.0
        max_p = 8
        if max_p >= n:
            max_p = n - 1
        defect_rate = total_d / n
        for p in range(3, max_p + 1):
            window = 30
            if n - p < window:
                window = n - p
            if window < 8:
                continue
            start2 = n - window
            cnt = 0
            match = 0
            for i in range(start2, n - p):
                cnt += 1
                if op[i] == op[i - p]:
                    match += 1
            if cnt >= 8:
                rate = match / cnt
                if rate > best_match:
                    best_match = rate
        if best_match >= 0.8 and 0.2 <= defect_rate <= 0.7:
            periodic = True

    if n >= 99:
        return 'D'

    if periodic:
        return 'D'

    if total_c == 0 and run_opp_d < 5:
        return 'D'

    forgives = 0
    punishes = 0
    for i in range(1, n):
        if me[i - 1] == 'D':
            if op[i] == 'C':
                forgives += 1
            else:
                punishes += 1

    if n == 50 and total_c == n and my_c == n:
        if rng.random() < 0.2:
            return 'D'

    if last_opp == 'C':
        if forgives >= 1 and punishes == 0 and total_ratio > 0.8:
            return 'D'
        return 'C'

    if last_me == 'C':
        if n >= 2 and me[-2] == 'D' and op[-2] == 'D':
            return 'C'
        if run_opp_d == 1 and recent_ratio >= 0.65:
            return 'C'
        return 'D'

    if recent_c == 0 and total_c == 0 and run_opp_d < 10:
        return 'D'

    run_start = n - run_opp_d
    first_check = run_start
    if first_check < 1:
        first_check = 1
    dd_starts = 0
    for i in range(first_check, n):
        if me[i] == 'C' and me[i - 1] == 'D' and op[i - 1] == 'D':
            dd_starts += 1

    next_try = 5 + 5 * dd_starts
    if dd_starts < 2 and run_opp_d >= next_try:
        return 'C'

    return 'D'
